V = [10 5 7]; I = [2 2 2]; into = [false true true];
P = V.*I; P(~into) = -P(~into);
for k = 1:3, fprintf('element %d: ', k); describe(P(k)); end

function describe(p)
    if p > 0, fprintf('p = %g W -> absorbs\n', p);
    elseif p < 0, fprintf('p = %g W -> delivers %g W\n', p, -p);
    else, fprintf('p = 0\n'); end
end
